export default [{"w":"affordability","pos":"noun","def":"The extent to which something is cheap enough for people to buy.","defId":"Keterjangkauan; sejauh mana sesuatu cukup murah untuk dibeli orang.","ex":"Rising prices have worsened housing affordability for young families.","exId":"Kenaikan harga telah memperburuk keterjangkauan perumahan bagi keluarga muda.","colloc":["housing affordability","an affordability crisis","improve affordability"],"theme":"economy"},{"w":"allocate","pos":"verb","def":"to give money, time, or resources to a particular purpose","defId":"memberikan uang, waktu, atau sumber daya untuk suatu tujuan tertentu; mengalokasikan","ex":"The board allocated a large budget to research and development.","exId":"Dewan direksi mengalokasikan anggaran besar untuk penelitian dan pengembangan.","colloc":["allocate resources","allocate funds","allocate a budget"],"theme":"economy"},{"w":"angel investor","pos":"noun","def":"A wealthy individual who provides money to a startup in its early stages.","defId":"Investor malaikat; individu kaya yang mendanai perusahaan rintisan pada tahap awal.","ex":"An angel investor gave the founders their first hundred thousand dollars.","exId":"Seorang investor malaikat memberi para pendiri seratus ribu dolar pertama mereka.","colloc":["attract angel investors","an angel investor","angel investor funding"],"theme":"economy"},{"w":"appreciation","pos":"noun","def":"an increase in the value of a currency or asset over time","defId":"apresiasi; kenaikan nilai mata uang atau aset seiring waktu","ex":"The steady appreciation of the local currency hurt exporters' competitiveness.","exId":"Apresiasi mata uang lokal yang stabil merugikan daya saing para eksportir.","colloc":["currency appreciation","capital appreciation"],"theme":"economy"},{"w":"arbitrage","pos":"noun","def":"The practice of buying and selling in different markets to profit from price differences.","defId":"Arbitrase; praktik membeli dan menjual di pasar berbeda untuk meraih untung dari selisih harga.","ex":"Traders used arbitrage to exploit the price gap between the two exchanges.","exId":"Para pedagang memanfaatkan arbitrase untuk mengeksploitasi selisih harga antara dua bursa.","colloc":["an arbitrage opportunity","currency arbitrage","engage in arbitrage"],"theme":"economy"},{"w":"asset","pos":"noun","def":"something valuable that a person or company owns, such as money, property, or equipment","defId":"sesuatu yang berharga yang dimiliki seseorang atau perusahaan, seperti uang, properti, atau peralatan; aset","ex":"The company sold some of its assets to pay off its debts.","exId":"Perusahaan menjual sebagian asetnya untuk melunasi utang-utangnya.","colloc":["fixed assets","valuable asset","sell assets"],"theme":"economy"},{"w":"austerity","pos":"noun","def":"a government policy of reducing public spending to lower budget deficits","defId":"kebijakan penghematan; pengetatan anggaran pemerintah untuk menekan defisit","ex":"Years of austerity led to deep cuts in health and education budgets.","exId":"Bertahun-tahun kebijakan penghematan menyebabkan pemotongan besar pada anggaran kesehatan dan pendidikan.","colloc":["austerity measures","impose austerity"],"theme":"economy"},{"w":"bailout","pos":"noun","def":"financial help given to a company or country facing serious financial trouble","defId":"dana talangan; bantuan keuangan bagi perusahaan atau negara yang bermasalah","ex":"The struggling airline received a multi-billion-dollar bailout from the government.","exId":"Maskapai yang kesulitan itu menerima dana talangan miliaran dolar dari pemerintah.","colloc":["government bailout","bailout package"],"theme":"economy"},{"w":"balance of payments","pos":"noun","def":"a record of all economic transactions between one country and the rest of the world","defId":"neraca pembayaran; catatan seluruh transaksi ekonomi suatu negara dengan dunia luar","ex":"A persistent balance of payments deficit put pressure on the national currency.","exId":"Defisit neraca pembayaran yang terus-menerus menekan nilai mata uang nasional.","colloc":["balance of payments deficit","balance of payments crisis"],"theme":"economy"},{"w":"balance of trade","pos":"noun","def":"the difference between the value of a country's exports and its imports","defId":"neraca perdagangan; selisih nilai ekspor dan impor suatu negara","ex":"A worsening balance of trade reflected the country's growing reliance on imports.","exId":"Neraca perdagangan yang memburuk mencerminkan meningkatnya ketergantungan negara pada impor.","colloc":["balance of trade deficit","favourable balance of trade"],"theme":"economy"},{"w":"bankruptcy","pos":"noun","def":"the state of being unable to pay your debts, officially declared by a court","defId":"keadaan tidak mampu membayar utang, yang dinyatakan secara resmi oleh pengadilan; kebangkrutan atau pailit","ex":"The airline filed for bankruptcy after years of heavy losses.","exId":"Maskapai itu mengajukan kebangkrutan setelah bertahun-tahun mengalami kerugian besar.","colloc":["file for bankruptcy","face bankruptcy","declare bankruptcy"],"theme":"economy"},{"w":"bear market","pos":"noun","def":"A period during which share prices are falling and investors are pessimistic.","defId":"Pasar bearish; periode saat harga saham turun dan investor pesimis.","ex":"Many funds lost value when the bear market dragged on for months.","exId":"Banyak reksa dana kehilangan nilai ketika pasar bearish berlarut-larut selama berbulan-bulan.","colloc":["enter a bear market","a prolonged bear market","a bear market rally"],"theme":"economy"},{"w":"black market","pos":"noun","def":"illegal trade in goods or currencies that avoids official controls","defId":"pasar gelap; perdagangan ilegal yang menghindari kendali resmi","ex":"When goods became scarce, a thriving black market quickly emerged.","exId":"Ketika barang menjadi langka, pasar gelap yang ramai segera muncul.","colloc":["black market trade","thriving black market"],"theme":"economy"},{"w":"blue-chip","pos":"adjective","def":"Relating to shares in large, well-established and financially sound companies.","defId":"Blue-chip; berkaitan dengan saham perusahaan besar, mapan, dan sehat secara finansial.","ex":"Cautious investors often prefer blue-chip stocks for their stability.","exId":"Investor yang berhati-hati sering memilih saham blue-chip karena stabilitasnya.","colloc":["blue-chip stocks","a blue-chip company","blue-chip shares"],"theme":"economy"},{"w":"boom","pos":"noun","def":"a period of rapid economic growth and increased business activity","defId":"lonjakan; masa pertumbuhan ekonomi yang pesat","ex":"The housing boom drove prices to levels that many buyers could no longer afford.","exId":"Lonjakan properti mendorong harga ke tingkat yang tak lagi terjangkau bagi banyak pembeli.","colloc":["economic boom","housing boom"],"theme":"economy"},{"w":"boomtown","pos":"noun","def":"A town that grows very quickly because of sudden economic prosperity.","defId":"Kota yang berkembang pesat; kota yang tumbuh sangat cepat karena kemakmuran ekonomi yang mendadak.","ex":"The discovery of oil turned the quiet village into a thriving boomtown almost overnight.","exId":"Penemuan minyak mengubah desa yang sepi itu menjadi kota berkembang pesat nyaris dalam semalam.","colloc":["a mining boomtown","become a boomtown","a boomtown economy"],"theme":"economy"},{"w":"bull market","pos":"noun","def":"A period during which share prices are rising and investors are confident.","defId":"Pasar bullish; periode saat harga saham naik dan investor optimis.","ex":"Investors made large gains during the long bull market.","exId":"Para investor meraih keuntungan besar selama pasar bullish yang panjang.","colloc":["during a bull market","a raging bull market","a bull market run"],"theme":"economy"},{"w":"buoyant","pos":"adjective","def":"(Of an economy or market) successful and tending to rise or stay high.","defId":"Bergairah; (tentang ekonomi atau pasar) sedang kuat dan cenderung naik.","ex":"A buoyant housing market encouraged more people to put their homes up for sale.","exId":"Pasar perumahan yang bergairah mendorong lebih banyak orang menjual rumah mereka.","colloc":["a buoyant economy","buoyant demand","a buoyant market"],"theme":"economy"},{"w":"bust","pos":"noun","def":"a sudden collapse in economic activity following a period of growth","defId":"kejatuhan; keruntuhan aktivitas ekonomi setelah masa pertumbuhan","ex":"Every boom seems to be followed sooner or later by a painful bust.","exId":"Setiap lonjakan tampaknya cepat atau lambat diikuti oleh kejatuhan yang menyakitkan.","colloc":["boom and bust","market bust"],"theme":"economy"},{"w":"capital","pos":"noun","def":"wealth in the form of money or assets used to invest in producing goods","defId":"modal; kekayaan berupa uang atau aset untuk berinvestasi dalam produksi","ex":"The company needed to raise fresh capital to fund its expansion abroad.","exId":"Perusahaan itu perlu menghimpun modal baru untuk mendanai ekspansinya ke luar negeri.","colloc":["raise capital","capital investment"],"theme":"economy"},{"w":"capital flight","pos":"noun","def":"The rapid movement of money out of a country, usually because of instability.","defId":"Pelarian modal; perpindahan uang secara cepat ke luar negeri, biasanya karena ketidakstabilan.","ex":"Political turmoil triggered massive capital flight from the country.","exId":"Gejolak politik memicu pelarian modal besar-besaran dari negara itu.","colloc":["trigger capital flight","massive capital flight","stem capital flight"],"theme":"economy"},{"w":"capital gains","pos":"noun","def":"the profit made from selling an asset for more than it cost to buy","defId":"keuntungan modal; laba dari menjual aset di atas harga belinya","ex":"Investors were required to pay tax on the capital gains from selling their shares.","exId":"Para investor wajib membayar pajak atas keuntungan modal dari penjualan saham mereka.","colloc":["capital gains tax","realise capital gains"],"theme":"economy"},{"w":"central bank","pos":"noun","def":"the institution that manages a country's currency, money supply and interest rates","defId":"bank sentral; lembaga yang mengatur mata uang dan suku bunga suatu negara","ex":"The central bank raised interest rates in an effort to cool the overheating economy.","exId":"Bank sentral menaikkan suku bunga untuk mendinginkan perekonomian yang memanas.","colloc":["central bank governor","independent central bank"],"theme":"economy"},{"w":"circular economy","pos":"noun","def":"an economic model based on reusing, repairing and recycling to minimise waste","defId":"ekonomi sirkular; model ekonomi berbasis penggunaan ulang dan daur ulang untuk mengurangi limbah","ex":"A circular economy aims to keep materials in use for as long as possible.","exId":"Ekonomi sirkular bertujuan menjaga bahan tetap terpakai selama mungkin.","colloc":["circular economy model","transition to a circular economy"],"theme":"economy"},{"w":"commodity","pos":"noun","def":"a raw material or basic product that can be bought and sold, such as oil, gold, or coffee","defId":"bahan mentah atau produk dasar yang dapat diperjualbelikan, seperti minyak, emas, atau kopi; komoditas","ex":"Oil is one of the most heavily traded commodities in the world.","exId":"Minyak adalah salah satu komoditas yang paling banyak diperdagangkan di dunia.","colloc":["commodity prices","trade a commodity","commodity market"],"theme":"economy"},{"w":"comparative advantage","pos":"noun","def":"a country's ability to produce a good at a lower opportunity cost than others","defId":"keunggulan komparatif; kemampuan suatu negara memproduksi barang dengan biaya peluang lebih rendah","ex":"The nation has a comparative advantage in producing coffee and other tropical crops.","exId":"Negara itu memiliki keunggulan komparatif dalam memproduksi kopi dan tanaman tropis lainnya.","colloc":["comparative advantage in","gain a comparative advantage"],"theme":"economy"},{"w":"compensate","pos":"verb","def":"to pay someone money because they have suffered a loss or damage","defId":"membayar seseorang karena mereka mengalami kerugian atau kerusakan; memberi kompensasi","ex":"The firm agreed to compensate the workers for their lost wages.","exId":"Perusahaan setuju untuk memberi kompensasi kepada para pekerja atas upah yang hilang.","colloc":["compensate for","compensate workers","fully compensate"],"theme":"economy"},{"w":"cost of living","pos":"noun","def":"the amount of money needed to cover basic expenses such as food, housing and clothing","defId":"biaya hidup; jumlah uang untuk memenuhi kebutuhan dasar","ex":"The soaring cost of living has forced many families to cut back on non-essentials.","exId":"Melonjaknya biaya hidup memaksa banyak keluarga mengurangi pengeluaran yang tidak penting.","colloc":["rising cost of living","cost of living crisis"],"theme":"economy"},{"w":"cost-effective","pos":"adjective","def":"Giving good value or results in relation to the money spent.","defId":"Hemat biaya; memberi hasil yang sepadan dengan uang yang dikeluarkan.","ex":"Solar panels have become a cost-effective way to reduce energy bills.","exId":"Panel surya telah menjadi cara yang hemat biaya untuk menekan tagihan energi.","colloc":["a cost-effective solution","more cost-effective","a cost-effective way"],"theme":"economy"},{"w":"credit crunch","pos":"noun","def":"a sudden reduction in the availability of loans and credit from banks","defId":"krisis kredit; berkurangnya ketersediaan pinjaman dan kredit secara tiba-tiba","ex":"During the credit crunch, small firms found it nearly impossible to borrow.","exId":"Selama krisis kredit, perusahaan kecil hampir mustahil mendapatkan pinjaman.","colloc":["global credit crunch","severe credit crunch"],"theme":"economy"},{"w":"dearth","pos":"noun","def":"A scarcity or lack of something.","defId":"Kelangkaan; kekurangan sesuatu.","ex":"There is a dearth of skilled workers in the manufacturing sector.","exId":"Terdapat kelangkaan tenaga kerja terampil di sektor manufaktur.","colloc":["a dearth of talent","a dearth of investment","a dearth of jobs"],"theme":"economy"},{"w":"deficit","pos":"noun","def":"the amount by which money spent is greater than money received","defId":"selisih jumlah ketika uang yang dikeluarkan lebih besar daripada uang yang diterima; defisit","ex":"The government struggled to reduce its huge budget deficit.","exId":"Pemerintah kesulitan mengurangi defisit anggaran yang sangat besar.","colloc":["budget deficit","trade deficit","reduce the deficit"],"theme":"economy"},{"w":"deflation","pos":"noun","def":"a general fall in prices across an economy over a period of time","defId":"deflasi; penurunan harga secara umum dalam suatu perekonomian","ex":"Persistent deflation can be as damaging to an economy as high inflation.","exId":"Deflasi yang berkepanjangan bisa merusak perekonomian sama seperti inflasi tinggi.","colloc":["persistent deflation","risk of deflation"],"theme":"economy"},{"w":"deindustrialisation","pos":"noun","def":"The decline of manufacturing industry in a region or country.","defId":"Deindustrialisasi; kemerosotan industri manufaktur di suatu daerah atau negara.","ex":"Deindustrialisation left many former mining towns with high unemployment.","exId":"Deindustrialisasi membuat banyak bekas kota tambang mengalami pengangguran tinggi.","colloc":["rapid deindustrialisation","the effects of deindustrialisation","regional deindustrialisation"],"theme":"economy"},{"w":"depreciation","pos":"noun","def":"a fall in the value of a currency or asset over time","defId":"depresiasi; penurunan nilai mata uang atau aset seiring waktu","ex":"The depreciation of the currency boosted exports but raised the cost of imports.","exId":"Depresiasi mata uang mendorong ekspor tetapi menaikkan biaya impor.","colloc":["currency depreciation","rapid depreciation"],"theme":"economy"},{"w":"deregulation","pos":"noun","def":"the removal of government rules and controls from an industry or market","defId":"deregulasi; penghapusan aturan dan kendali pemerintah dari suatu industri","ex":"Deregulation of the airline industry led to lower fares and fiercer competition.","exId":"Deregulasi industri penerbangan menghasilkan tarif lebih rendah dan persaingan yang lebih ketat.","colloc":["market deregulation","financial deregulation"],"theme":"economy"},{"w":"destitute","pos":"adjective","def":"Without money, food, or the means to live; extremely poor.","defId":"Melarat; tanpa uang, makanan, atau sarana untuk hidup; sangat miskin.","ex":"The floods left thousands of families destitute and homeless.","exId":"Banjir itu membuat ribuan keluarga melarat dan kehilangan tempat tinggal.","colloc":["left destitute","utterly destitute","the destitute poor"],"theme":"economy"},{"w":"devaluation","pos":"noun","def":"a deliberate reduction in the official value of a currency against others","defId":"devaluasi; penurunan resmi nilai mata uang terhadap mata uang lain","ex":"The sudden devaluation of the currency made imports far more expensive.","exId":"Devaluasi mata uang yang mendadak membuat barang impor jauh lebih mahal.","colloc":["currency devaluation","sharp devaluation"],"theme":"economy"},{"w":"diminishing returns","pos":"noun","def":"the point at which extra input yields progressively smaller increases in output","defId":"hasil yang menurun; titik di mana tambahan input memberi hasil yang makin kecil","ex":"After a certain point, hiring more workers brought diminishing returns.","exId":"Setelah titik tertentu, menambah pekerja justru memberi hasil yang makin menurun.","colloc":["law of diminishing returns","diminishing returns set in"],"theme":"economy"},{"w":"diversify","pos":"verb","def":"to start to make new products or offer new services in order to be more successful","defId":"mulai membuat produk baru atau menawarkan jasa baru agar lebih sukses; melakukan diversifikasi","ex":"The company diversified into online sales to reduce its risks.","exId":"Perusahaan melakukan diversifikasi ke penjualan daring untuk mengurangi risikonya.","colloc":["diversify into","diversify the economy","diversify a portfolio"],"theme":"economy"},{"w":"dividend","pos":"noun","def":"a part of a company's profit that is paid to the people who own shares in it","defId":"bagian dari keuntungan perusahaan yang dibayarkan kepada para pemilik saham; dividen","ex":"The company paid its shareholders a higher dividend this year.","exId":"Perusahaan membayar dividen yang lebih tinggi kepada para pemegang sahamnya tahun ini.","colloc":["pay a dividend","annual dividend","dividend payment"],"theme":"economy"},{"w":"downturn","pos":"noun","def":"a fall in the amount of business activity or in the economy","defId":"penurunan dalam aktivitas bisnis atau perekonomian; kelesuan","ex":"The economic downturn forced many companies to freeze hiring.","exId":"Kelesuan ekonomi memaksa banyak perusahaan menghentikan perekrutan.","colloc":["economic downturn","sharp downturn","downturn in demand"],"theme":"economy"},{"w":"economies of scale","pos":"noun","def":"the cost savings a firm gains by producing goods in larger quantities","defId":"skala ekonomi; penghematan biaya karena memproduksi dalam jumlah besar","ex":"By merging, the two companies hoped to achieve economies of scale and cut costs.","exId":"Dengan bergabung, kedua perusahaan berharap mencapai skala ekonomi dan menekan biaya.","colloc":["achieve economies of scale","benefit from economies of scale"],"theme":"economy"},{"w":"entrepreneur","pos":"noun","def":"a person who starts a business and takes financial risks in the hope of making a profit","defId":"orang yang memulai usaha dan mengambil risiko keuangan dengan harapan memperoleh keuntungan; wirausahawan","ex":"The young entrepreneur launched three successful start-ups before turning thirty.","exId":"Wirausahawan muda itu mendirikan tiga perusahaan rintisan yang sukses sebelum berusia tiga puluh tahun.","colloc":["successful entrepreneur","young entrepreneur","social entrepreneur"],"theme":"economy"},{"w":"exchange rate","pos":"noun","def":"the value of one currency expressed in terms of another","defId":"nilai tukar; nilai suatu mata uang terhadap mata uang lain","ex":"A volatile exchange rate makes it hard for businesses to plan overseas trade.","exId":"Nilai tukar yang bergejolak menyulitkan perusahaan merencanakan perdagangan luar negeri.","colloc":["floating exchange rate","exchange rate fluctuations"],"theme":"economy"},{"w":"expenditure","pos":"noun","def":"the amount of money that a person, organization, or government spends","defId":"jumlah uang yang dikeluarkan oleh seseorang, organisasi, atau pemerintah; pengeluaran","ex":"The government cut public expenditure to reduce its debt.","exId":"Pemerintah memangkas belanja publik untuk mengurangi utangnya.","colloc":["public expenditure","reduce expenditure","total expenditure"],"theme":"economy"},{"w":"fiscal","pos":"adjective","def":"relating to government revenue, spending and taxation","defId":"fiskal; berkaitan dengan pendapatan, belanja, dan pajak pemerintah","ex":"The minister promised tighter fiscal discipline to bring down the deficit.","exId":"Menteri berjanji menerapkan disiplin fiskal yang lebih ketat untuk menurunkan defisit.","colloc":["fiscal policy","fiscal deficit"],"theme":"economy"},{"w":"fluctuate","pos":"verb","def":"to change often in level, amount, or value, going up and down","defId":"sering berubah dalam tingkat, jumlah, atau nilai, naik dan turun; berfluktuasi","ex":"Oil prices fluctuate depending on global supply and demand.","exId":"Harga minyak berfluktuasi tergantung pada pasokan dan permintaan global.","colloc":["prices fluctuate","fluctuate wildly","fluctuate between"],"theme":"economy"},{"w":"foreclosure","pos":"noun","def":"The legal process by which a lender takes possession of a property when the owner fails to pay the mortgage.","defId":"Penyitaan rumah; proses hukum saat pemberi pinjaman menyita properti karena pemilik gagal membayar cicilan.","ex":"Falling house prices led to a wave of foreclosures across the region.","exId":"Anjloknya harga rumah memicu gelombang penyitaan rumah di seluruh kawasan itu.","colloc":["face foreclosure","a wave of foreclosures","foreclosure proceedings"],"theme":"economy"},{"w":"foreign exchange","pos":"noun","def":"the trading of one currency for another, or the currencies themselves","defId":"valuta asing; perdagangan atau mata uang antarnegara","ex":"The country holds large reserves of foreign exchange to defend its currency.","exId":"Negara itu memiliki cadangan valuta asing yang besar untuk mempertahankan mata uangnya.","colloc":["foreign exchange reserves","foreign exchange market"],"theme":"economy"},{"w":"frugality","pos":"noun","def":"The quality of being economical and sparing with money or food.","defId":"Kehematan; sikap berhemat dalam pengeluaran uang atau makanan.","ex":"Years of frugality during the recession helped the couple pay off their debts.","exId":"Bertahun-tahun berhemat selama resesi membantu pasangan itu melunasi utang mereka.","colloc":["strict frugality","a life of frugality","enforced frugality"],"theme":"economy"},{"w":"full employment","pos":"noun","def":"a situation in which almost everyone who wants a job is able to find one","defId":"kesempatan kerja penuh; kondisi hampir semua yang ingin bekerja mendapat pekerjaan","ex":"The government set full employment as one of its main economic goals.","exId":"Pemerintah menetapkan kesempatan kerja penuh sebagai salah satu tujuan ekonomi utamanya.","colloc":["achieve full employment","near full employment"],"theme":"economy"},{"w":"furlough","pos":"noun","def":"A temporary leave of workers, often without pay, during a downturn.","defId":"Perumahan sementara; pemberhentian pekerja untuk sementara, sering tanpa upah, saat kelesuan ekonomi.","ex":"Thousands of staff were placed on furlough when the factories closed.","exId":"Ribuan pekerja dirumahkan sementara ketika pabrik-pabrik tutup.","colloc":["on furlough","a furlough scheme","place on furlough"],"theme":"economy"},{"w":"gig economy","pos":"noun","def":"a labour market based on short-term, freelance or on-demand jobs rather than permanent ones","defId":"ekonomi gig; pasar kerja berbasis pekerjaan lepas atau jangka pendek","ex":"Many young workers rely on the gig economy, delivering food or driving for apps.","exId":"Banyak pekerja muda mengandalkan ekonomi gig, mengantar makanan atau menjadi sopir aplikasi.","colloc":["gig economy workers","rise of the gig economy"],"theme":"economy"},{"w":"glut","pos":"noun","def":"A supply of something that is far greater than the demand for it.","defId":"Kelebihan pasokan; jumlah barang yang jauh melebihi permintaan.","ex":"A global glut of oil pushed prices down to record lows.","exId":"Kelebihan pasokan minyak global menekan harga ke titik terendah.","colloc":["a glut of supply","an oil glut","a market glut"],"theme":"economy"},{"w":"gross domestic product","pos":"noun","def":"the total value of all goods and services produced within a country in a given period","defId":"produk domestik bruto (total nilai barang dan jasa yang dihasilkan suatu negara)","ex":"The country's gross domestic product grew by three per cent last year, signalling a healthy recovery.","exId":"Produk domestik bruto negara itu tumbuh tiga persen tahun lalu, menandakan pemulihan yang sehat.","colloc":["gross domestic product grew","measure gross domestic product"],"theme":"economy"},{"w":"handout","pos":"noun","def":"Money or goods given free to someone in need, often by the state.","defId":"Bantuan cuma-cuma; uang atau barang yang diberikan gratis kepada yang membutuhkan, sering oleh negara.","ex":"Critics argued that generous handouts discouraged people from finding work.","exId":"Para pengkritik berpendapat bahwa bantuan cuma-cuma yang murah hati membuat orang enggan mencari kerja.","colloc":["government handouts","rely on handouts","cash handouts"],"theme":"economy"},{"w":"hedge fund","pos":"noun","def":"An investment fund that uses risky strategies to try to earn high returns.","defId":"Dana lindung nilai (hedge fund); dana investasi yang memakai strategi berisiko demi imbal hasil tinggi.","ex":"The hedge fund bet heavily against the falling currency.","exId":"Hedge fund itu bertaruh besar melawan mata uang yang sedang jatuh.","colloc":["a hedge fund manager","run a hedge fund","hedge fund investors"],"theme":"economy"},{"w":"hyperinflation","pos":"noun","def":"extremely rapid and out-of-control rises in prices across an economy","defId":"hiperinflasi; kenaikan harga yang sangat cepat dan tak terkendali","ex":"Hyperinflation wiped out people's savings almost overnight.","exId":"Hiperinflasi memusnahkan tabungan masyarakat hampir dalam semalam.","colloc":["rampant hyperinflation","trigger hyperinflation"],"theme":"economy"},{"w":"incentive","pos":"noun","def":"something that encourages a person or company to do something, such as work harder","defId":"sesuatu yang mendorong seseorang atau perusahaan untuk melakukan sesuatu, misalnya bekerja lebih keras; insentif","ex":"The company offered a cash bonus as an incentive to boost sales.","exId":"Perusahaan menawarkan bonus tunai sebagai insentif untuk meningkatkan penjualan.","colloc":["financial incentive","offer an incentive","tax incentive"],"theme":"economy"},{"w":"indebted","pos":"adjective","def":"Owing money; in debt.","defId":"Berutang; menanggung utang.","ex":"Many students remain heavily indebted for years after graduating.","exId":"Banyak mahasiswa tetap terlilit utang berat selama bertahun-tahun setelah lulus.","colloc":["heavily indebted","deeply indebted","an indebted nation"],"theme":"economy"},{"w":"indicator","pos":"noun","def":"a statistic used to measure or predict the state of the economy","defId":"indikator; statistik untuk mengukur atau memprediksi kondisi ekonomi","ex":"Unemployment is a key indicator of the overall health of the economy.","exId":"Tingkat pengangguran adalah indikator utama kesehatan perekonomian secara keseluruhan.","colloc":["economic indicator","leading indicator"],"theme":"economy"},{"w":"inflation","pos":"noun","def":"a general rise in prices that reduces the value of money over time","defId":"kenaikan harga secara umum yang mengurangi nilai uang seiring waktu; inflasi","ex":"Rising inflation made everyday goods much more expensive for families.","exId":"Inflasi yang meningkat membuat barang sehari-hari menjadi jauh lebih mahal bagi keluarga.","colloc":["rising inflation","inflation rate","control inflation"],"theme":"economy"},{"w":"informal economy","pos":"noun","def":"economic activity that is not taxed, regulated or officially recorded","defId":"ekonomi informal; kegiatan ekonomi yang tidak dipajaki atau dicatat resmi","ex":"Millions of people earn their living in the informal economy, without contracts or benefits.","exId":"Jutaan orang mencari nafkah di ekonomi informal, tanpa kontrak atau tunjangan.","colloc":["informal economy workers","thriving informal economy"],"theme":"economy"},{"w":"insolvent","pos":"adjective","def":"Unable to pay debts owed because liabilities exceed assets.","defId":"Tak mampu bayar/bangkrut; tidak dapat melunasi utang karena kewajiban melebihi aset.","ex":"The airline was declared insolvent after failing to repay its lenders.","exId":"Maskapai itu dinyatakan bangkrut setelah gagal membayar para krediturnya.","colloc":["declared insolvent","become insolvent","technically insolvent"],"theme":"economy"},{"w":"interest rate","pos":"noun","def":"the percentage charged by a lender for borrowing money, or paid on savings","defId":"suku bunga; persentase biaya pinjaman atau imbalan tabungan","ex":"A rise in the interest rate makes mortgages and loans more expensive.","exId":"Kenaikan suku bunga membuat kredit rumah dan pinjaman menjadi lebih mahal.","colloc":["raise interest rates","benchmark interest rate"],"theme":"economy"},{"w":"labour market","pos":"noun","def":"the supply of and demand for workers and available jobs in an economy","defId":"pasar tenaga kerja; penawaran dan permintaan pekerja serta lapangan kerja","ex":"A tight labour market pushed wages up as employers competed for staff.","exId":"Pasar tenaga kerja yang ketat mendorong kenaikan upah saat pengusaha berebut pekerja.","colloc":["tight labour market","labour market reform"],"theme":"economy"},{"w":"laissez-faire","pos":"adjective","def":"Favouring minimal government interference in economic affairs.","defId":"Laissez-faire; menganjurkan campur tangan pemerintah yang minimal dalam urusan ekonomi.","ex":"Supporters of a laissez-faire approach argue that markets work best when left alone.","exId":"Pendukung pendekatan laissez-faire berpendapat bahwa pasar bekerja paling baik jika dibiarkan.","colloc":["a laissez-faire approach","laissez-faire economics","laissez-faire policies"],"theme":"economy"},{"w":"levy","pos":"noun","def":"an amount of money, such as a tax, that must be paid to a government or authority","defId":"pungutan; sejumlah uang seperti pajak yang wajib dibayar kepada pemerintah","ex":"The government imposed a new levy on sugary drinks to improve public health.","exId":"Pemerintah menerapkan pungutan baru atas minuman manis untuk meningkatkan kesehatan masyarakat.","colloc":["impose a levy","import levy"],"theme":"economy"},{"w":"liability","pos":"noun","def":"an amount of money that a person or company owes; a debt","defId":"sejumlah uang yang harus dibayar oleh seseorang atau perusahaan; kewajiban atau utang","ex":"The firm's liabilities were greater than its assets, so it went bankrupt.","exId":"Kewajiban perusahaan itu lebih besar daripada asetnya, sehingga perusahaan itu bangkrut.","colloc":["financial liability","limited liability","total liabilities"],"theme":"economy"},{"w":"liquidity","pos":"noun","def":"the availability of cash or assets that can quickly be turned into cash","defId":"likuiditas; ketersediaan uang tunai atau aset yang mudah dicairkan","ex":"During the crisis, many banks faced a severe shortage of liquidity.","exId":"Selama krisis, banyak bank menghadapi kekurangan likuiditas yang parah.","colloc":["market liquidity","liquidity crisis"],"theme":"economy"},{"w":"lucrative","pos":"adjective","def":"producing a lot of money; very profitable","defId":"menghasilkan banyak uang; sangat menguntungkan","ex":"Selling software abroad proved to be a lucrative business for the firm.","exId":"Menjual perangkat lunak ke luar negeri terbukti menjadi bisnis yang sangat menguntungkan bagi perusahaan itu.","colloc":["lucrative business","lucrative deal","lucrative market"],"theme":"economy"},{"w":"macroeconomics","pos":"noun","def":"the branch of economics that studies the economy as a whole","defId":"makroekonomi; cabang ilmu ekonomi yang mempelajari perekonomian secara keseluruhan","ex":"Macroeconomics examines issues such as inflation, growth and unemployment.","exId":"Makroekonomi mengkaji isu seperti inflasi, pertumbuhan, dan pengangguran.","colloc":["study macroeconomics","modern macroeconomics"],"theme":"economy"},{"w":"means-tested","pos":"adjective","def":"(Of benefits) given only to people whose income is below a certain level.","defId":"Berdasarkan uji kemampuan ekonomi; (tentang tunjangan) hanya diberikan kepada orang berpenghasilan di bawah batas tertentu.","ex":"The grant is means-tested, so only low-income households qualify.","exId":"Hibah itu berbasis uji kemampuan ekonomi, sehingga hanya rumah tangga berpenghasilan rendah yang memenuhi syarat.","colloc":["a means-tested benefit","means-tested support","strictly means-tested"],"theme":"economy"},{"w":"merger","pos":"noun","def":"the joining of two companies to form one larger company","defId":"penggabungan dua perusahaan menjadi satu perusahaan yang lebih besar; merger","ex":"The merger of the two airlines created the largest carrier in the region.","exId":"Penggabungan kedua maskapai itu menciptakan maskapai terbesar di kawasan tersebut.","colloc":["propose a merger","merger deal","company merger"],"theme":"economy"},{"w":"microeconomics","pos":"noun","def":"the branch of economics that studies individual markets, firms and consumers","defId":"mikroekonomi; cabang ekonomi yang mempelajari pasar, perusahaan, dan konsumen individu","ex":"Microeconomics helps explain how prices are set for a single product.","exId":"Mikroekonomi membantu menjelaskan bagaimana harga sebuah produk ditetapkan.","colloc":["basic microeconomics","microeconomics theory"],"theme":"economy"},{"w":"microfinance","pos":"noun","def":"The provision of very small loans to poor people to help them start businesses.","defId":"Keuangan mikro; pemberian pinjaman sangat kecil kepada orang miskin untuk memulai usaha.","ex":"Microfinance has helped many rural women set up their own shops.","exId":"Keuangan mikro telah membantu banyak perempuan desa mendirikan toko mereka sendiri.","colloc":["a microfinance institution","microfinance loans","access to microfinance"],"theme":"economy"},{"w":"monetary","pos":"adjective","def":"relating to money supply, interest rates and the actions of a central bank","defId":"moneter; berkaitan dengan jumlah uang beredar dan suku bunga","ex":"Tight monetary policy was used to curb runaway inflation.","exId":"Kebijakan moneter yang ketat digunakan untuk menekan inflasi yang tak terkendali.","colloc":["monetary policy","monetary tightening"],"theme":"economy"},{"w":"money supply","pos":"noun","def":"the total amount of money circulating in an economy at a given time","defId":"jumlah uang beredar; total uang yang beredar dalam perekonomian","ex":"Rapid growth in the money supply is often blamed for rising inflation.","exId":"Pertumbuhan cepat jumlah uang beredar sering disalahkan atas naiknya inflasi.","colloc":["expand the money supply","control the money supply"],"theme":"economy"},{"w":"monopoly","pos":"noun","def":"complete control of a product or service by one company, with no competition","defId":"penguasaan penuh atas suatu produk atau jasa oleh satu perusahaan tanpa persaingan; monopoli","ex":"The firm was accused of holding a monopoly over the country's phone network.","exId":"Perusahaan itu dituduh memegang monopoli atas jaringan telepon negara tersebut.","colloc":["hold a monopoly","state monopoly","break up a monopoly"],"theme":"economy"},{"w":"national debt","pos":"noun","def":"the total amount of money that a country's government owes to lenders","defId":"utang nasional; total uang yang dipinjam pemerintah suatu negara","ex":"The national debt has ballooned after years of heavy government borrowing.","exId":"Utang nasional membengkak setelah bertahun-tahun pemerintah banyak berutang.","colloc":["rising national debt","service the national debt"],"theme":"economy"},{"w":"nationalisation","pos":"noun","def":"the transfer of a private business or industry into state ownership","defId":"nasionalisasi; pengalihan usaha swasta menjadi milik negara","ex":"The nationalisation of the failing bank was intended to protect savers.","exId":"Nasionalisasi bank yang bangkrut itu dimaksudkan untuk melindungi para penabung.","colloc":["nationalisation of industry","full nationalisation"],"theme":"economy"},{"w":"negotiate","pos":"verb","def":"to try to reach an agreement through formal discussion","defId":"berusaha mencapai kesepakatan melalui perundingan resmi; bernegosiasi","ex":"The union negotiated a better pay deal with the management.","exId":"Serikat pekerja bernegosiasi untuk mendapatkan kesepakatan gaji yang lebih baik dengan manajemen.","colloc":["negotiate a deal","negotiate a contract","negotiate terms"],"theme":"economy"},{"w":"opulence","pos":"noun","def":"Great wealth and luxury.","defId":"Kemewahan; kekayaan dan kemewahan yang melimpah.","ex":"The mansion's opulence reflected the family's vast business fortune.","exId":"Kemewahan rumah besar itu mencerminkan kekayaan bisnis keluarga tersebut yang luar biasa.","colloc":["sheer opulence","a display of opulence","surrounded by opulence"],"theme":"economy"},{"w":"outlay","pos":"noun","def":"An amount of money spent on something, especially as an initial investment.","defId":"Pengeluaran; sejumlah uang yang dibelanjakan, terutama sebagai modal awal.","ex":"Setting up the workshop required a large initial outlay on machinery.","exId":"Mendirikan bengkel itu memerlukan pengeluaran awal yang besar untuk mesin.","colloc":["initial outlay","a capital outlay","a large outlay"],"theme":"economy"},{"w":"outsource","pos":"verb","def":"to pay another company to do work that was previously done inside your own company","defId":"membayar perusahaan lain untuk mengerjakan pekerjaan yang sebelumnya dilakukan di dalam perusahaan sendiri; mengalihdayakan","ex":"The bank decided to outsource its customer service to another country.","exId":"Bank itu memutuskan untuk mengalihdayakan layanan pelanggannya ke negara lain.","colloc":["outsource work","outsource production","outsource services"],"theme":"economy"},{"w":"overheads","pos":"noun","def":"the regular costs of running a business, such as rent and electricity","defId":"biaya rutin untuk menjalankan bisnis, seperti sewa dan listrik; biaya operasional tetap","ex":"The company moved to a smaller office to reduce its overheads.","exId":"Perusahaan pindah ke kantor yang lebih kecil untuk mengurangi biaya operasionalnya.","colloc":["reduce overheads","high overheads","fixed overheads"],"theme":"economy"},{"w":"penury","pos":"noun","def":"The state of being extremely poor.","defId":"Kemiskinan parah; keadaan sangat melarat.","ex":"After the business collapsed, the family was reduced to penury.","exId":"Setelah usaha itu bangkrut, keluarga tersebut jatuh ke dalam kemiskinan parah.","colloc":["reduced to penury","live in penury","lifelong penury"],"theme":"economy"},{"w":"per capita","pos":"adjective/adverb","def":"calculated for or in relation to each person in a population","defId":"per kapita; dihitung untuk setiap orang dalam suatu populasi","ex":"Although the economy is huge overall, per capita income remains fairly low.","exId":"Meskipun perekonomiannya besar secara keseluruhan, pendapatan per kapita tetap cukup rendah.","colloc":["per capita income","per capita GDP"],"theme":"economy"},{"w":"poverty line","pos":"noun","def":"The minimum level of income deemed adequate to meet basic living needs.","defId":"Garis kemiskinan; batas pendapatan minimum yang dianggap cukup untuk memenuhi kebutuhan hidup dasar.","ex":"Millions of families still live below the poverty line despite years of economic growth.","exId":"Jutaan keluarga masih hidup di bawah garis kemiskinan meskipun ekonomi telah tumbuh bertahun-tahun.","colloc":["below the poverty line","fall below the poverty line","the official poverty line"],"theme":"economy"},{"w":"price stability","pos":"noun","def":"a situation in which prices in the economy remain steady over time","defId":"stabilitas harga; kondisi harga yang tetap stabil dari waktu ke waktu","ex":"The central bank's main goal is to maintain price stability across the economy.","exId":"Tujuan utama bank sentral adalah menjaga stabilitas harga di seluruh perekonomian.","colloc":["maintain price stability","achieve price stability"],"theme":"economy"},{"w":"privatisation","pos":"noun","def":"the transfer of a business or industry from state to private ownership","defId":"privatisasi; pengalihan usaha atau industri dari milik negara ke swasta","ex":"The privatisation of the railways remains a controversial political issue.","exId":"Privatisasi jalur kereta api tetap menjadi isu politik yang kontroversial.","colloc":["mass privatisation","privatisation programme"],"theme":"economy"},{"w":"procurement","pos":"noun","def":"the process of obtaining the supplies or equipment that a company or government needs","defId":"proses memperoleh pasokan atau peralatan yang dibutuhkan perusahaan atau pemerintah; pengadaan","ex":"The procurement team searched for cheaper suppliers to cut costs.","exId":"Tim pengadaan mencari pemasok yang lebih murah untuk menekan biaya.","colloc":["public procurement","procurement process","procurement costs"],"theme":"economy"},{"w":"productivity","pos":"noun","def":"the rate at which a worker, company, or country produces goods, compared with the resources used","defId":"tingkat kecepatan seorang pekerja, perusahaan, atau negara menghasilkan barang dibandingkan dengan sumber daya yang digunakan; produktivitas","ex":"New technology helped raise productivity across the whole factory.","exId":"Teknologi baru membantu meningkatkan produktivitas di seluruh pabrik.","colloc":["increase productivity","labour productivity","productivity growth"],"theme":"economy"},{"w":"profitable","pos":"adjective","def":"Producing a financial gain or benefit.","defId":"Menguntungkan; menghasilkan keuntungan finansial.","ex":"The factory only became profitable after it switched to cheaper materials.","exId":"Pabrik itu baru menguntungkan setelah beralih ke bahan yang lebih murah.","colloc":["highly profitable","a profitable venture","profitable margins"],"theme":"economy"},{"w":"prosperity","pos":"noun","def":"the state of being successful and having a lot of money","defId":"keadaan sukses dan memiliki banyak uang; kemakmuran","ex":"The new trade deal brought years of prosperity to the region.","exId":"Kesepakatan dagang baru itu membawa kemakmuran selama bertahun-tahun bagi kawasan tersebut.","colloc":["economic prosperity","bring prosperity","growing prosperity"],"theme":"economy"},{"w":"purchasing power","pos":"noun","def":"the amount of goods and services that a unit of money can buy","defId":"daya beli; jumlah barang dan jasa yang dapat dibeli dengan sejumlah uang","ex":"Rising prices have steadily eroded the purchasing power of ordinary wage earners.","exId":"Kenaikan harga terus-menerus menggerus daya beli pekerja bergaji biasa.","colloc":["erode purchasing power","purchasing power parity"],"theme":"economy"},{"w":"quantitative easing","pos":"noun","def":"A policy in which a central bank creates money to buy assets and stimulate the economy.","defId":"Pelonggaran kuantitatif; kebijakan bank sentral mencetak uang untuk membeli aset guna merangsang ekonomi.","ex":"The central bank launched quantitative easing to revive lending during the crisis.","exId":"Bank sentral meluncurkan pelonggaran kuantitatif untuk menghidupkan kembali penyaluran kredit selama krisis.","colloc":["a programme of quantitative easing","launch quantitative easing","quantitative easing measures"],"theme":"economy"},{"w":"quota","pos":"noun","def":"an official limit on the amount or number of something, especially imports","defId":"kuota; batas resmi jumlah sesuatu, terutama impor","ex":"An import quota was set to protect local farmers from cheap foreign produce.","exId":"Kuota impor ditetapkan untuk melindungi petani lokal dari produk asing yang murah.","colloc":["import quota","production quota"],"theme":"economy"},{"w":"rally","pos":"verb","def":"(Of prices or markets) to recover and rise again after a fall.","defId":"Pulih dan naik kembali (tentang harga atau pasar) setelah menurun.","ex":"Share prices began to rally as soon as the central bank cut interest rates.","exId":"Harga saham mulai pulih naik begitu bank sentral memangkas suku bunga.","colloc":["stocks rally","markets rally","rally sharply"],"theme":"economy"},{"w":"recession","pos":"noun","def":"a period when the economy of a country is not doing well and business activity falls","defId":"periode ketika perekonomian suatu negara memburuk dan aktivitas bisnis menurun; resesi","ex":"Many small businesses closed down during the deep recession.","exId":"Banyak usaha kecil gulung tikar selama resesi yang parah.","colloc":["deep recession","economic recession","slip into recession"],"theme":"economy"},{"w":"redundancy","pos":"noun","def":"a situation in which someone loses their job because they are no longer needed","defId":"keadaan ketika seseorang kehilangan pekerjaan karena tidak lagi dibutuhkan; pemutusan hubungan kerja (PHK)","ex":"The factory closure led to hundreds of redundancies in the town.","exId":"Penutupan pabrik itu menyebabkan ratusan pemutusan hubungan kerja di kota tersebut.","colloc":["face redundancy","compulsory redundancy","redundancy pay"],"theme":"economy"},{"w":"remuneration","pos":"noun","def":"the money paid to someone for the work they have done; pay","defId":"uang yang dibayarkan kepada seseorang atas pekerjaan yang telah dilakukannya; imbalan","ex":"The job offers generous remuneration along with health benefits.","exId":"Pekerjaan itu menawarkan imbalan yang besar disertai tunjangan kesehatan.","colloc":["generous remuneration","remuneration package","annual remuneration"],"theme":"economy"},{"w":"reshoring","pos":"noun","def":"The practice of bringing manufacturing or services back to a company's home country.","defId":"Reshoring; praktik memindahkan kembali produksi atau jasa ke negara asal perusahaan.","ex":"Rising shipping costs have encouraged the reshoring of some factories.","exId":"Naiknya biaya pengiriman mendorong reshoring sebagian pabrik.","colloc":["the reshoring of jobs","encourage reshoring","a reshoring trend"],"theme":"economy"},{"w":"revenue","pos":"noun","def":"the money that a company or government receives, especially from selling goods or services","defId":"uang yang diterima perusahaan atau pemerintah, terutama dari penjualan barang atau jasa; pendapatan","ex":"The company's annual revenue rose by ten percent after it launched the new product.","exId":"Pendapatan tahunan perusahaan itu naik sepuluh persen setelah meluncurkan produk baru.","colloc":["annual revenue","generate revenue","revenue growth"],"theme":"economy"},{"w":"self-sufficiency","pos":"noun","def":"The ability to provide for one's own needs without outside help.","defId":"Swasembada; kemampuan memenuhi kebutuhan sendiri tanpa bantuan pihak luar.","ex":"The government's policy aims to achieve self-sufficiency in food production.","exId":"Kebijakan pemerintah bertujuan mencapai swasembada dalam produksi pangan.","colloc":["achieve self-sufficiency","food self-sufficiency","economic self-sufficiency"],"theme":"economy"},{"w":"shareholder","pos":"noun","def":"a person who owns shares in a company and therefore owns part of it","defId":"orang yang memiliki saham dalam suatu perusahaan dan karenanya memiliki sebagian dari perusahaan itu; pemegang saham","ex":"The shareholders voted against the chief executive's new plan.","exId":"Para pemegang saham menolak rencana baru direktur utama itu.","colloc":["major shareholder","shareholder value","shareholders vote"],"theme":"economy"},{"w":"shortfall","pos":"noun","def":"An amount by which something is less than what is needed or expected.","defId":"Kekurangan; selisih jumlah yang kurang dari yang dibutuhkan atau diharapkan.","ex":"The company faced a serious budget shortfall after sales dropped sharply.","exId":"Perusahaan menghadapi kekurangan anggaran yang serius setelah penjualan anjlok tajam.","colloc":["a budget shortfall","make up the shortfall","a revenue shortfall"],"theme":"economy"},{"w":"sovereign debt","pos":"noun","def":"Money borrowed by a national government.","defId":"Utang negara; uang yang dipinjam oleh pemerintah suatu negara.","ex":"The country struggled to repay its mounting sovereign debt.","exId":"Negara itu kesulitan melunasi utang negaranya yang terus membengkak.","colloc":["a sovereign debt crisis","repay sovereign debt","default on sovereign debt"],"theme":"economy"},{"w":"stagnant","pos":"adjective","def":"Not growing or developing; showing no activity or progress.","defId":"Stagnan; tidak tumbuh atau berkembang; tanpa aktivitas maupun kemajuan.","ex":"Wages have remained stagnant while the cost of living keeps rising.","exId":"Upah tetap stagnan sementara biaya hidup terus meningkat.","colloc":["stagnant wages","a stagnant economy","remain stagnant"],"theme":"economy"},{"w":"stakeholder","pos":"noun","def":"a person or group with an interest in a business or its decisions, such as workers or investors","defId":"orang atau kelompok yang memiliki kepentingan dalam sebuah bisnis atau keputusannya, seperti pekerja atau investor; pemangku kepentingan","ex":"The company consulted every stakeholder before changing its strategy.","exId":"Perusahaan berkonsultasi dengan setiap pemangku kepentingan sebelum mengubah strateginya.","colloc":["key stakeholder","engage stakeholders","stakeholder interests"],"theme":"economy"},{"w":"stimulus","pos":"noun","def":"government action, such as spending or tax cuts, intended to encourage economic growth","defId":"stimulus; tindakan pemerintah untuk mendorong pertumbuhan ekonomi","ex":"The central bank introduced a massive stimulus package to revive demand.","exId":"Bank sentral memperkenalkan paket stimulus besar-besaran untuk menghidupkan kembali permintaan.","colloc":["stimulus package","fiscal stimulus"],"theme":"economy"},{"w":"subsidy","pos":"noun","def":"money paid by a government to help an industry or to keep prices low","defId":"uang yang dibayarkan pemerintah untuk membantu suatu industri atau menjaga harga tetap rendah; subsidi","ex":"Farmers rely on government subsidies to keep their prices competitive.","exId":"Para petani mengandalkan subsidi pemerintah untuk menjaga harga mereka tetap bersaing.","colloc":["government subsidy","farm subsidy","cut subsidies"],"theme":"economy"},{"w":"surplus","pos":"noun","def":"an amount of something that is more than what is needed or used","defId":"jumlah sesuatu yang lebih banyak daripada yang dibutuhkan atau digunakan; surplus","ex":"The country produced a trade surplus by exporting more than it imported.","exId":"Negara itu mencatatkan surplus perdagangan dengan mengekspor lebih banyak daripada mengimpor.","colloc":["trade surplus","budget surplus","surplus goods"],"theme":"economy"},{"w":"tariff","pos":"noun","def":"a tax that a government charges on goods coming into or leaving a country","defId":"pajak yang dikenakan pemerintah atas barang yang masuk ke atau keluar dari suatu negara; tarif atau bea","ex":"The government raised tariffs on imported steel to protect local producers.","exId":"Pemerintah menaikkan tarif atas baja impor untuk melindungi produsen dalam negeri.","colloc":["import tariff","impose tariffs","raise tariffs"],"theme":"economy"},{"w":"taxation","pos":"noun","def":"the system by which a government collects money from people and businesses","defId":"perpajakan; sistem pemungutan uang oleh pemerintah dari warga dan usaha","ex":"Higher taxation on the wealthy was proposed to fund public services.","exId":"Perpajakan yang lebih tinggi bagi orang kaya diusulkan untuk mendanai layanan publik.","colloc":["progressive taxation","corporate taxation"],"theme":"economy"},{"w":"thrift","pos":"noun","def":"Careful management of money and resources to avoid waste.","defId":"Sifat hemat; pengelolaan uang dan sumber daya secara cermat agar tidak boros.","ex":"Her habits of thrift allowed her to save enough to start a small business.","exId":"Kebiasaan hematnya memungkinkan dia menabung cukup untuk memulai usaha kecil.","colloc":["a culture of thrift","practise thrift","habits of thrift"],"theme":"economy"},{"w":"thrive","pos":"verb","def":"to grow, develop, or be successful, especially in business","defId":"tumbuh, berkembang, atau berhasil, terutama dalam bisnis; berkembang pesat","ex":"Small shops thrived after the new shopping district opened.","exId":"Toko-toko kecil berkembang pesat setelah kawasan perbelanjaan baru dibuka.","colloc":["thrive on","businesses thrive","thrive in a market"],"theme":"economy"},{"w":"turnover","pos":"noun","def":"the total amount of money a business earns in a period, or the rate at which staff leave and are replaced","defId":"total uang yang diperoleh suatu bisnis dalam suatu periode, atau tingkat pergantian karyawan; omzet atau perputaran","ex":"The restaurant had an annual turnover of two million dollars.","exId":"Restoran itu memiliki omzet tahunan sebesar dua juta dolar.","colloc":["annual turnover","staff turnover","high turnover"],"theme":"economy"},{"w":"underemployment","pos":"noun","def":"a situation where people work fewer hours or below their skill level than they want","defId":"pengangguran terselubung; kondisi bekerja di bawah kapasitas atau keahlian","ex":"Official figures hid widespread underemployment among part-time workers.","exId":"Angka resmi menyembunyikan pengangguran terselubung yang luas di kalangan pekerja paruh waktu.","colloc":["widespread underemployment","tackle underemployment"],"theme":"economy"},{"w":"unemployment","pos":"noun","def":"the situation in which people who want to work cannot find a job","defId":"keadaan ketika orang yang ingin bekerja tidak dapat menemukan pekerjaan; pengangguran","ex":"Unemployment rose sharply during the economic crisis as many factories closed.","exId":"Angka pengangguran meningkat tajam selama krisis ekonomi karena banyak pabrik tutup.","colloc":["high unemployment","unemployment rate","rising unemployment"],"theme":"economy"},{"w":"upswing","pos":"noun","def":"An upward trend in business activity or economic conditions.","defId":"Peningkatan; tren naik dalam aktivitas bisnis atau kondisi ekonomi.","ex":"Retailers reported a strong upswing in demand during the holiday season.","exId":"Para peritel melaporkan peningkatan permintaan yang kuat selama musim liburan.","colloc":["an economic upswing","a cyclical upswing","on the upswing"],"theme":"economy"},{"w":"upturn","pos":"noun","def":"an improvement or rise in economic activity after a difficult period","defId":"pemulihan; peningkatan aktivitas ekonomi setelah masa sulit","ex":"Retailers reported a welcome upturn in sales as consumer confidence returned.","exId":"Peritel melaporkan pemulihan penjualan yang menggembirakan saat kepercayaan konsumen kembali.","colloc":["economic upturn","sharp upturn"],"theme":"economy"},{"w":"venture","pos":"noun","def":"a new business activity, especially one that involves risk","defId":"kegiatan bisnis baru, terutama yang mengandung risiko; usaha atau ventura","ex":"The two firms started a joint venture to build electric cars.","exId":"Kedua perusahaan itu memulai usaha patungan untuk membuat mobil listrik.","colloc":["joint venture","business venture","new venture"],"theme":"economy"},{"w":"venture capital","pos":"noun","def":"Money invested in new or growing businesses that carry a high risk.","defId":"Modal ventura; dana yang diinvestasikan pada bisnis baru atau berkembang yang berisiko tinggi.","ex":"The startup raised millions in venture capital to expand overseas.","exId":"Perusahaan rintisan itu menggalang jutaan modal ventura untuk berekspansi ke luar negeri.","colloc":["raise venture capital","a venture capital firm","venture capital funding"],"theme":"economy"},{"w":"viable","pos":"adjective","def":"able to work successfully, especially in making a profit","defId":"mampu berjalan dengan sukses, terutama dalam menghasilkan keuntungan; layak","ex":"The bank refused the loan because the business plan was not financially viable.","exId":"Bank menolak pinjaman itu karena rencana bisnisnya tidak layak secara finansial.","colloc":["commercially viable","viable option","economically viable"],"theme":"economy"},{"w":"wage","pos":"noun","def":"a regular amount of money paid to a worker, usually weekly, for the work they do","defId":"sejumlah uang yang dibayarkan secara berkala kepada pekerja, biasanya setiap minggu, atas pekerjaan mereka; upah","ex":"Many workers protested because their wages had not risen for years.","exId":"Banyak pekerja berunjuk rasa karena upah mereka tidak naik selama bertahun-tahun.","colloc":["minimum wage","raise wages","low wages"],"theme":"economy"},{"w":"workforce","pos":"noun","def":"all the people who work for a particular company or in a particular country","defId":"seluruh orang yang bekerja untuk suatu perusahaan atau di suatu negara; tenaga kerja","ex":"The company reduced its workforce by two hundred employees last year.","exId":"Perusahaan itu mengurangi tenaga kerjanya sebanyak dua ratus karyawan tahun lalu.","colloc":["skilled workforce","reduce the workforce","global workforce"],"theme":"economy"}];
